urlset:
{{ range readDir "static" }}
{{ if and (not .IsDir) (eq (path.Ext .Name) ".html") (ne .Name "thank-you.html") }}
{{ $slug := .Name }}
{{ if eq $slug "index.html" }}{{ $slug = "" }}{{ end }}

    {{ $.Site.BaseURL }}{{ $slug }}

{{ end }}
{{ end }}
{{ range .Site.Pages }}
{{ if and (not .Draft) (ne .Kind "404") }}

    {{ .Permalink }}
    {{ .Lastmod.Format "2006-01-02" }}

{{ end }}
{{ end }}
